#!/usr/bin/env node
// Cross-checks the independent JS transcription of the CTU-level CABAC syntax
// layer (tools/syntax_lib.mjs) against the authoritative truth that the real
// upstream Go code produced (tools/syntax_golden.json, generated by
// tools/export_syntax_golden_test.go from gen2brain/h265).
//
//   node tools/crosscheck_syntax.mjs
//
// The Go export calls the real upstream pure derivations (lossyMPM / splitCtx /
// chroma422Map / chromaQP / QP wrap / saoMaxOffset) and round-trips every
// syntax element through the real cabacWriter -> real ctuDecoder readers. Here
// every value is re-derived from the from-the-spec JS transcription, and every
// CABAC bitstream is decoded by the JS decoder. Zero differences is the bar,
// matching the earlier M3 rounds. No Go toolchain or network in CI.

import fs from 'fs';
import path from 'path';
import { fileURLToPath } from 'url';
import {
  newDecoder, mpmCand, splitCuCtx, splitTfCtx, cbfLumaCtx, cbfCbCrCtx,
  chroma422, chromaQP, qpWrap, saoOffsetCMax,
  decodeIntraLumaMode, decodeIntraChromaMode, decodeCuQPDelta,
  decodeCuChromaQPOffset, decodePartModeIntra, decodeSAO,
} from './syntax_lib.mjs';

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const g = JSON.parse(fs.readFileSync(path.join(root, 'tools/syntax_golden.json'), 'utf8'));

let checks = 0;
function eq(got, want, what) {
  checks++;
  if (got !== want) throw new Error(`${what}: got ${got}, want ${want}`);
}
function eqArr(got, want, what) {
  checks++;
  const a = Array.from(got), b = Array.from(want);
  if (a.length !== b.length || a.some((v, i) => v !== b[i]))
    throw new Error(`${what}: got [${a}], want [${b}]`);
}
const bytes = (s) => Uint8Array.from(Buffer.from(s, 'base64'));

// ---- pure derivations, full traversal ----------------------------------
for (const t of g.mpm) {
  const a = t.A < 0 ? 1 : t.A, b = t.B < 0 ? 1 : t.B; // absent => intraDC
  eqArr(mpmCand(a, b), t.Want, `mpm(A=${t.A},B=${t.B})`);
}
for (const t of g.split_cu_ctx)
  eq(splitCuCtx(t.LeftDepth, t.AboveDepth, t.Depth), t.Want,
    `splitCuCtx(${t.LeftDepth},${t.AboveDepth},${t.Depth})`);
for (const t of g.ctx_idx) {
  const got = t.Kind === 'split_tf' ? splitTfCtx(t.A)
    : t.Kind === 'cbf_luma' ? cbfLumaCtx(t.A) : cbfCbCrCtx(t.A);
  eq(got, t.Want, `ctxIdx(${t.Kind},${t.A})`);
}
for (let i = 0; i < g.chroma422.length; i++)
  eq(chroma422(i), g.chroma422[i], `chroma422(${i})`);
for (let q = 0; q < g.chroma_qp.length; q++)
  eq(chromaQP(q, 1), g.chroma_qp[q], `chromaQP(${q})`);
for (const t of g.qp_wrap)
  eq(qpWrap(t.Pred, t.Delta, 8), t.Want, `qpWrap(${t.Pred},${t.Delta})`);
for (const t of g.sao_cmax)
  eq(saoOffsetCMax(t.BitDepth), t.Want, `saoOffsetCMax(${t.BitDepth})`);

// ---- syntax-element round trips: JS decoder vs Go bytes ----------------
for (const t of g.bin_cases) {
  const c = newDecoder(bytes(t.Bytes));
  eq(c.decodeBin(t.Ctx), t.Want, `bin(${t.Kind},ctx=${t.Ctx})`);
}
for (const t of g.part_cases) {
  const c = newDecoder(bytes(t.Bytes));
  eq(decodePartModeIntra(c), t.Want, `partMode(intra)`);
}
for (const t of g.luma_cases) {
  const c = newDecoder(bytes(t.Bytes));
  eq(decodeIntraLumaMode(c, t.Cand), t.Want,
    `intraLuma(A=${t.A},B=${t.B},cand=${t.Cand},mode=${t.Mode})`);
}
for (const t of g.chroma_cases) {
  const c = newDecoder(bytes(t.Bytes));
  eq(decodeIntraChromaMode(c, t.Luma, 1), t.Want,
    `intraChroma(luma=${t.Luma},idx=${t.Idx},direct=${t.Direct})`);
}
for (const t of g.qpd_cases) {
  const c = newDecoder(bytes(t.Bytes));
  eq(decodeCuQPDelta(c), t.Want, `cuQPDelta(abs=${t.Abs},sign=${t.Sign})`);
}
for (const t of g.cqo_cases) {
  const c = newDecoder(bytes(t.Bytes));
  const got = decodeCuChromaQPOffset(c, t.Len, t.CbList, t.CrList);
  eq(got.cb, t.WantCb, `cuChromaQPOffset(flag=${t.Flag},l=${t.Len},idx=${t.Idx}).cb`);
  eq(got.cr, t.WantCr, `cuChromaQPOffset(flag=${t.Flag},l=${t.Len},idx=${t.Idx}).cr`);
}
for (const t of g.sao_cases) {
  const c = newDecoder(bytes(t.Bytes));
  const got = decodeSAO(c, 8, 0, 0);
  for (let k = 0; k < 3; k++) {
    eq(got[k].typeIdx, t.Types[k], `sao(${t.Label})[${k}].typeIdx`);
    eqArr(got[k].offset, t.Offs[k], `sao(${t.Label})[${k}].offset`);
    eq(got[k].band, t.Bands[k], `sao(${t.Label})[${k}].band`);
    eq(got[k].class, t.Classes[k], `sao(${t.Label})[${k}].class`);
  }
}

console.log(`crosscheck_syntax: ${checks} values, zero differences`);
